                                                                                         typ=type(self)))
            return _invalid_op

        cls.__mul__ = cls.__rmul__ = _make_invalid_op('multiplication')
        cls.__floordiv__ = cls.__rfloordiv__ = _make_invalid_op('floor division')
        cls.__truediv__ = cls.__rtruediv__ = _make_invalid_op('true division')
        if not compat.PY3:
